import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/*
 * Generates two files from mobile-web/_worker.js, the one hand-written server:
 *   - self-hosted/cloudflare-worker/worker.js: the same worker plus the web app's files embedded, for
 *     deploying to a plain Cloudflare Worker (`npm run deploy:cf`) instead of Cloudflare Pages
 *   - self-hosted/server/calendarFeed.js: the calendar feed section, used by the local Node server and Vercel
 * Edit mobile-web/_worker.js, then run `npm run build` (or `npm run bundle:worker`).
 */

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const WEB_DIR = path.join(ROOT, 'mobile-web');
const PAGES_WORKER = path.join(WEB_DIR, '_worker.js');
const OUTPUT_WORKER = path.join(ROOT, 'self-hosted', 'cloudflare-worker', 'worker.js');
const OUTPUT_FEED = path.join(ROOT, 'self-hosted', 'server', 'calendarFeed.js');

const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.webmanifest': 'application/manifest+json',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8'
};
const BINARY = new Set(['.png', '.ico', '.woff2']);

const readText = file => fs.readFileSync(file, 'utf8').replace(/\r\n?/g, '\n');

function writeIfChanged(file, content) {
  const existing = fs.existsSync(file) ? readText(file) : null;
  if (existing === content) return;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, 'utf8');
}

const workerSource = readText(PAGES_WORKER);

// 1. self-hosted/server/calendarFeed.js
const FEED_START = /^\/\/ ---- calendar feed start[^\n]*\n/m;
const FEED_END = /^\/\/ ---- calendar feed end ----\n/m;
const startMatch = FEED_START.exec(workerSource);
const endMatch = FEED_END.exec(workerSource);
if (!startMatch || !endMatch) {
  throw new Error('mobile-web/_worker.js is missing the "calendar feed start/end" markers');
}
const feedCode = workerSource.slice(startMatch.index + startMatch[0].length, endMatch.index).trimEnd();
writeIfChanged(OUTPUT_FEED, `/**
 * RFC 5545 iCalendar (.ics) feed generator for the local Node server and Vercel functions.
 * Generated by scripts/bundle-worker.js from mobile-web/_worker.js - edit that file, not this one.
 */

${feedCode}

export {
  generateIcsFeed,
  escapeIcsText,
  formatUtcTimestamp,
  formatDateOnly
};
`);

// 2. self-hosted/cloudflare-worker/worker.js
if (!/^export default \{/m.test(workerSource)) {
  throw new Error('mobile-web/_worker.js must end with "export default { ... }"');
}
const pagesWorkerCode = workerSource.replace(/^export default \{/m, 'const pagesWorker = {');

const assets = {};
function embedDir(dir, prefix) {
  for (const name of fs.readdirSync(dir).sort()) {
    const full = path.join(dir, name);
    if (fs.statSync(full).isDirectory()) { embedDir(full, `${prefix}${name}/`); continue; }
    if (name === '_worker.js') continue;
    const ext = path.extname(name).toLowerCase();
    if (!CONTENT_TYPES[ext]) continue;
    assets[`${prefix}${name}`] = BINARY.has(ext)
      ? { contentType: CONTENT_TYPES[ext], base64: fs.readFileSync(full).toString('base64') }
      : { contentType: CONTENT_TYPES[ext], content: readText(full) };
  }
}
embedDir(WEB_DIR, '/');

const output = `/**
 * Cloudflare Worker for Blackboarder: the Pages worker (mobile-web/_worker.js) with the web app's
 * files embedded, so it runs on a plain Worker without Cloudflare Pages.
 * Generated by scripts/bundle-worker.js - edit mobile-web/_worker.js, not this file.
 */

${pagesWorkerCode}

const EMBEDDED_ASSETS = ${JSON.stringify(assets)};

function decodeBase64(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// Stands in for the env.ASSETS binding that Cloudflare Pages provides
const embeddedAssetsBinding = {
  async fetch(request) {
    let pathname = new URL(request.url).pathname;
    if (pathname === '' || pathname.endsWith('/')) pathname += 'index.html';
    if (pathname === '/companion') pathname = '/companion/index.html';
    // Unknown companion paths get the companion shell; anything else gets the landing page
    const shell = pathname.startsWith('/companion/') ? '/companion/index.html' : '/index.html';
    const asset = EMBEDDED_ASSETS[pathname] || EMBEDDED_ASSETS[shell];
    const body = asset.base64 !== undefined ? decodeBase64(asset.base64) : asset.content;
    return new Response(body, {
      status: 200,
      headers: { 'Content-Type': asset.contentType, 'Access-Control-Allow-Origin': '*' }
    });
  }
};

export default {
  fetch(request, env, ctx) {
    // Calendar links made for the old standalone worker used ?token= instead of ?key=
    const url = new URL(request.url);
    if (!url.searchParams.has('key') && url.searchParams.has('token')) {
      url.searchParams.set('key', url.searchParams.get('token'));
      request = new Request(url.toString(), request);
    }
    return pagesWorker.fetch(request, { ...(env || {}), ASSETS: embeddedAssetsBinding }, ctx);
  }
};
`;

writeIfChanged(OUTPUT_WORKER, output);
console.log('Generated self-hosted/cloudflare-worker/worker.js and self-hosted/server/calendarFeed.js from mobile-web/_worker.js');
